121	    });
122	
123	    it('totalPrice sinkt, wenn ein Sitzplatz mit zugeordneter Kategorie abgewählt wird', () => {
124	      const service = createService();
125	      service.setPriceCategories([{ id: 10, name: 'Kategorie A', preis: 25 }]);
126	      service.toggle('A', 1);
127	      service.assignCategory('A', 1, 10);
128	      service.toggle('A', 1);
129	      expect(service.totalPrice()).toBe(0);
130	    });
131	    ```
