9	public class EventsController(EventQueryService eventQueryService, EventDetailService eventDetailService, SeatMapService seatMapService) : ControllerBase
10	{
11	    [HttpGet]
12	    public async Task<ActionResult<IEnumerable<EventSummaryDto>>> GetEvents([FromQuery] DateOnly? von, [FromQuery] DateOnly? bis, [FromQuery] int? venueId, CancellationToken ct)
13	    {
14	        var summaries = await eventQueryService.GetEventSummariesAsync(von, bis, venueId, ct);
15	        return Ok(summaries.Select(s => new EventSummaryDto(s.Id, s.Titel, s.Spielstaette, s.Zeitpunkt)));
16	    }
