18	    [HttpGet("{id:int}")]
19	    public async Task<ActionResult<EventDetailDto>> GetEvent(int id, CancellationToken ct)
20	    {
21	        var detail = await eventDetailService.GetEventDetailAsync(id, ct);
22	        if (detail is null)
23	        {
24	            return NotFound(new ErrorEnvelopeDto("EVENT_NOT_FOUND", "Veranstaltung nicht gefunden."));
25	        }
26	
27	        return Ok(new EventDetailDto(
28	            detail.Id, detail.Titel, detail.Beschreibung, detail.DauerMinuten, detail.Altersfreigabe,
29	            detail.Spielstaette, detail.Raum, detail.Zeitpunkt,
30	            detail.Preiskategorien.Select(pc => new PriceCategoryDto(pc.Id, pc.Name, pc.Preis)).ToList()));
31	    }
32	
33	    [HttpGet("{id:int}/seatmap")]
34	    public async Task<ActionResult<SeatMapDto>> GetSeatMap(int id, CancellationToken ct)
35	    {
36	        var seatMap = await seatMapService.GetSeatMapAsync(id, ct);
37	        if (seatMap is null)
38	        {
39	            return NotFound(new ErrorEnvelopeDto("EVENT_NOT_FOUND", "Veranstaltung nicht gefunden."));
40	        }
41	
42	        return Ok(new SeatMapDto(
43	            seatMap.RowLabels, seatMap.ColumnCount, seatMap.AisleColumns,
44	            seatMap.Rows.Select(r => new SeatMapRowDto(
45	                r.RowLabel, r.Cells.Select(c => new SeatMapCellDto(c.ColumnNumber, c.Status)).ToList())).ToList()));
46	    }
47	}
