@use 'breakpoints' as *;

:root {
  // Colors
  --color-background: #F7F5F1;
  --color-surface: #FFFFFF;
  --color-surface-variant: #ECE8E2;
  --color-surface-container: #F1EEE8;
  --color-on-surface: #201C2B;
  --color-on-surface-variant: #5B5568;
  --color-outline: #8A8396;
  --color-outline-variant: #D6D1DC;
  --color-primary: #2E2452;
  --color-on-primary: #FFFFFF;
  --color-primary-container: #E4DEF2;
  --color-on-primary-container: #241A47;
  --color-accent: #8A4B12;
  --color-on-accent: #FFFFFF;
  --color-accent-container: #F5E3D0;
  --color-on-accent-container: #4A2708;
  --color-success: #2E7D4F;
  --color-on-success: #FFFFFF;
  --color-error: #B3261E;
  --color-on-error: #FFFFFF;
  --color-error-container: #FBDCD9;
  --color-on-error-container: #601410;
  --color-seat-free-bg: #FFFFFF;
  --color-seat-free-border: #8A8396;
  --color-seat-selected-bg: #2E2452;
  --color-seat-selected-on: #FFFFFF;
  --color-seat-occupied-bg: #DAD5E0;
  --color-seat-occupied-mark: #5B5568;
  --color-seat-aisle-bg: #F7F5F1;

  // Typography
  --font-display: 'Fraunces', Georgia, serif;
  --font-body: 'Inter', system-ui, sans-serif;
  --text-title-size: 18px;
  --text-title-weight: 600;
  --text-body-size: 16px;
  --text-body-sm-size: 14px;
  --text-headline-size: 22px;
  --text-headline-weight: 500;
  --text-price-display-size: 20px;
  --text-price-display-weight: 700;

  // Spacing (8px base grid)
  --space-1: 8px;
  --space-2: 16px;
  --space-3: 24px;
  --space-4: 32px;
  --space-5: 40px;
  --space-6: 48px;
  --gutter: 24px;
  --margin-mobile: 16px;
  --margin-desktop: 48px;

  // Radii
  --radius-sm: 4px;
  --radius-default: 8px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;

  // Sitzplan
  --seat-gap: 6px;
  --seat-cell-size: 34px;
  --text-seat-label-size: 11px;
  --text-seat-label-weight: 600;
}

@media (min-width: $breakpoint-tablet) {
  :root {
    --seat-cell-size: 40px;
  }
}

html,
body {
  margin: 0;
  padding: 0;
  background: var(--color-background);
  color: var(--color-on-surface);
  font-family: var(--font-body);
  font-size: var(--text-body-size);
}

@if (loading()) {
  <p class="event-detail__loading">Veranstaltung wird geladen…</p>
} @else if (notFound()) {
  <p class="event-detail__error" role="alert">Veranstaltung nicht gefunden.</p>
} @else if (loadError()) {
  <p class="event-detail__error" role="alert">Veranstaltungsdetails konnten nicht geladen werden. Bitte versuchen Sie es später erneut.</p>
} @else if (event(); as e) {
  <article class="event-detail">
    <h1 class="event-detail__title">{{ e.titel }}</h1>
    <p class="event-detail__description">{{ e.beschreibung }}</p>
    <dl class="event-detail__meta">
      <dt>Spielstätte</dt>
      <dd>{{ e.spielstaette }}</dd>
      <dt>Raum</dt>
      <dd>{{ e.raum }}</dd>
      <dt>Zeitpunkt</dt>
      <dd>{{ e.zeitpunkt | date:'EEEE, d. MMMM y, HH:mm' }} Uhr</dd>
      <dt>Dauer</dt>
      <dd>{{ e.dauerMinuten }} Minuten</dd>
      <dt>Altersfreigabe</dt>
      <dd>{{ e.altersfreigabe === 0 ? 'Keine Altersbeschränkung' : 'Ab ' + e.altersfreigabe + ' Jahren' }}</dd>
    </dl>
    <a class="event-detail__book-button button-primary" [routerLink]="['/veranstaltungen', e.id, 'buchung']">Plätze wählen</a>
  </article>
}

