@use '../../../breakpoints' as *;

.event-detail {
  padding: var(--margin-mobile);
}

.event-detail__title {
  margin: var(--space-3) 0 var(--space-2);
  font-family: var(--font-display);
  font-size: var(--text-headline-size);
  font-weight: var(--text-headline-weight);
  color: var(--color-on-surface);
}

.event-detail__description {
  margin: 0 0 var(--space-3);
  font-family: var(--font-body);
  font-size: var(--text-body-size);
  color: var(--color-on-surface);
}

.event-detail__meta {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: var(--space-1) var(--space-2);
  font-family: var(--font-body);
  font-size: var(--text-body-sm-size);
}

.event-detail__meta dt {
  font-weight: 600;
  color: var(--color-on-surface-variant);
}

.event-detail__meta dd {
  margin: 0;
  color: var(--color-on-surface);
}

.event-detail__loading {
  padding: var(--space-3) var(--margin-mobile);
  color: var(--color-on-surface-variant);
  font-family: var(--font-body);
  font-size: var(--text-body-size);
}

.event-detail__error {
  margin: var(--space-3) var(--margin-mobile);
  padding: var(--space-2) var(--space-3);
  background: var(--color-error-container);
  color: var(--color-on-error-container);
  border-radius: var(--radius-default);
  font-family: var(--font-body);
  font-size: var(--text-body-size);
}

@media (min-width: $breakpoint-tablet) {
  .event-detail {
    padding: var(--margin-desktop);
  }
}

.event-detail__book-button {
  display: inline-block;
  margin-top: var(--space-2);
  text-decoration: none;
  text-align: center;
}

.button-primary {
  background: var(--color-primary);
  color: var(--color-on-primary);
  border: none;
  border-radius: var(--radius-md);
  padding-block: 12px;
  padding-inline: var(--space-3);
  font-family: var(--font-body);
  font-size: var(--text-body-size);
  font-weight: 600;
  cursor: pointer;
}

